# DBTITLE 1,Stream Consumer Template - Overview
# MAGIC %md
# MAGIC # Stream Consumer Template
# MAGIC
# MAGIC ## Purpose
# MAGIC Demonstrates how to consume streaming data generated by `00_bronze_to_stream_generator` using standard Spark Structured Streaming.
# MAGIC
# MAGIC ## Concepts Demonstrated
# MAGIC - ✅ `spark.readStream` setup (standard Spark, not Auto Loader)
# MAGIC - ✅ 10-minute watermark (late data handling)
# MAGIC - ✅ 30-minute session windows
# MAGIC - ✅ Checkpoint configuration
# MAGIC - ✅ Stop/restart for checkpoint testing
# MAGIC - ✅ Stateful aggregations
# MAGIC
# MAGIC ## Prerequisites
# MAGIC 1. Run `00_bronze_to_stream_generator` first to create streaming batches
# MAGIC 2. Volume `/Volumes/sap_dev/bronze/streaming_test_data` must exist with CSV files
# MAGIC
# MAGIC ## Run Instructions
# MAGIC - Run cells sequentially
# MAGIC - Observe streaming output
# MAGIC - Stop and restart to test checkpoints

# COMMAND ----------

# DBTITLE 1,Configuration
# MAGIC %run ../../../1_Canvas/1_Setup/1_config

# COMMAND ----------

# DBTITLE 1,Notebook Parameters (derived from Config)
# Extract paths from Config for convenience
volume_path = Config.VOLUME_PATH
checkpoint_path = Config.CHECKPOINT_BASE + "/stream_consumer_template"

print(f"✅ Parameters configured:")
print(f"  Volume Path: {volume_path}")
print(f"  Checkpoint Path: {checkpoint_path}")

# COMMAND ----------

# DBTITLE 1,Read Stream (Standard Spark Streaming)
from pyspark.sql import functions as F
from pyspark.sql.types import *

# Define schema (matches realistic generator output - 38 fields from stg_sales + streaming columns)
schema = StructType([
    StructField("CustomerID", LongType(), True),
    StructField("OrderID", IntegerType(), True),
    StructField("CustomerName", StringType(), True),
    StructField("CustomerAge", LongType(), True),
    StructField("CustomerGender", StringType(), True),
    StructField("CustomerAddress", StringType(), True),
    StructField("CustomerContact", StringType(), True),
    StructField("CustomerMail", StringType(), True),
    StructField("ProductName", StringType(), True),
    StructField("ProductCategory", StringType(), True),
    StructField("MFDDate", DateType(), True),
    StructField("EXPDate", DateType(), True),
    StructField("OrderDate", DateType(), True),
    StructField("DeliveryDate", DateType(), True),
    StructField("CostPrice", DoubleType(), True),
    StructField("SellingPrice", DoubleType(), True),
    StructField("DiscountPercentage", DoubleType(), True),
    StructField("Discount", DoubleType(), True),
    StructField("CGST", DoubleType(), True),
    StructField("SGST", DoubleType(), True),
    StructField("finalPrice", DoubleType(), True),
    StructField("ProductQuantity", IntegerType(), True),
    StructField("TotalAmount", DoubleType(), True),
    StructField("WareHouseName", StringType(), True),
    StructField("WareHouseCity", StringType(), True),
    StructField("PaymentMode", StringType(), True),
    StructField("AgentName", StringType(), True),
    StructField("AgentCity", StringType(), True),
    StructField("AgentContact", StringType(), True),
    StructField("AgentMail", StringType(), True),
    StructField("RetailerName", StringType(), True),
    StructField("RetailerCity", StringType(), True),
    StructField("RetailerContact", StringType(), True),
    StructField("RetailerMail", StringType(), True),
    StructField("BatchDate", DateType(), True),
    StructField("LoadedAt", TimestampType(), True),
    StructField("event_timestamp", TimestampType(), True),
    StructField("session_id", LongType(), True)
])

# Read stream using standard Spark (NOT cloudFiles/Auto Loader)
df_stream = (
    spark.readStream
    .format("csv")
    .option("header", "true")
    .schema(schema)
    .option("maxFilesPerTrigger", 1)  # Process 1 file per micro-batch
    .load(volume_path)
)

print("✅ Stream reader configured")
print(f"\nSchema:")
df_stream.printSchema()

# COMMAND ----------

# DBTITLE 1,Apply Watermark (Late Data Handling)
# Apply 10-minute watermark
# Events >10 minutes late will be DROPPED
df_watermarked = df_stream.withWatermark("event_timestamp", "10 minutes")

print("✅ Watermark applied: 10 minutes")
print("\nLate data behavior:")
print("  - Events ≤10 min late: ACCEPTED")
print("  - Events >10 min late: DROPPED")

# COMMAND ----------

# DBTITLE 1,Session Window Aggregation (30-min Timeout)
# Session window aggregation
# Sessions close after 30 minutes of inactivity
df_sessions = (
    df_watermarked
    .groupBy(
        F.session_window("event_timestamp", "30 minutes"),
        "session_id"
    )
    .agg(
        F.count("*").alias("event_count"),
        F.sum("TotalAmount").alias("session_total"),
        F.min("event_timestamp").alias("session_start"),
        F.max("event_timestamp").alias("session_end")
    )
    .select(
        F.col("session_window.start").alias("window_start"),
        F.col("session_window.end").alias("window_end"),
        "session_id",
        "event_count",
        "session_total",
        "session_start",
        "session_end"
    )
)

print("✅ Session windows configured: 30-minute timeout")

# COMMAND ----------

# DBTITLE 1,Write Stream to Console (For Testing)
# Write to console for observation
# NOTE: Serverless compute requires availableNow (batch-like) trigger
query = (
    df_sessions.writeStream
    .outputMode("complete")  # Session windows require 'complete' or 'append' mode
    .format("console")
    .option("truncate", "false")
    .option("checkpointLocation", checkpoint_path)
    .trigger(availableNow=True)  # Process all available files then stop (serverless compatible)
    .start()
)

print("✅ Stream started!")
print(f"\nQuery ID: {query.id}")
print(f"Status: {query.status}")
print("\n👁️ Processing all available batches...")
print("\n⏸️ Stream will auto-stop after processing (availableNow mode)")
print("\n📝 Note: Serverless doesn't support continuous streaming (processingTime trigger)")
print("    Use availableNow for batch-like processing or Once for single micro-batch")

# COMMAND ----------

# DBTITLE 1,Monitor Stream Status
# Check if query is active
if query.isActive:
    print("✅ Stream is ACTIVE")
    print(f"\nLast progress:")
    print(query.lastProgress)
else:
    print("⚠️ Stream is STOPPED")

# COMMAND ----------

# DBTITLE 1,Stop Stream (Checkpoint Test)
# Stop the stream to test checkpoint recovery
query.stop()
print("⏹️ Stream STOPPED")
print("\n📋 Checkpoint saved state")
print("\nNext steps:")
print("1. Wait for more batches from generator (or generate more manually)")
print("2. Re-run the stream cells above")
print("3. Observe: Stream resumes from checkpoint (no duplicates!)")

# COMMAND ----------

# DBTITLE 1,Testing Checklist
# MAGIC %md
# MAGIC ## Testing Checklist
# MAGIC
# MAGIC ### ✅ Watermark Test
# MAGIC 1. Observe output - some events should be dropped (>10 min late)
# MAGIC 2. Check `lastProgress` for `numRowsDroppedByWatermark`
# MAGIC
# MAGIC ### ✅ Session Window Test
# MAGIC 1. Watch sessions open as events arrive
# MAGIC 2. Sessions close after 30 min of inactivity
# MAGIC 3. `window_start` and `window_end` show session boundaries
# MAGIC
# MAGIC ### ✅ Checkpoint Test
# MAGIC 1. Run stream → Stop after processing 5 batches
# MAGIC 2. Generate more batches (re-run generator)
# MAGIC 3. Restart stream → Resumes from checkpoint
# MAGIC 4. Verify: No duplicate processing
# MAGIC
# MAGIC ### ✅ Incremental Processing Test
# MAGIC 1. Stream processes 1 file per trigger (`maxFilesPerTrigger=1`)
# MAGIC 2. Each micro-batch shows incremental progress
# MAGIC 3. State accumulates across batches
